  };

  const createAdminUser = async (event) => {
    event.preventDefault();
    try {
      const token = getAuthToken();
      const response = await fetch('/api/auth/admin/users', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
