        phone_number: '',
        password: '',
        department: 'General',
        role: 'employee',
        job_position_title: 'Staff',
        employer: 'Okoa Float Ltd',
        is_superuser: false,
      });
      setMessage({ type: 'success', text: 'User created successfully.' });
      await loadSuperAdminData();
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    }
  };

  const updateAdminUserRole = async (userId, nextRole, isSuperUser) => {
    try {
      const token = getAuthToken();
      const response = await fetch(`/api/auth/admin/users/${userId}/role`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ role: nextRole, is_superuser: Boolean(isSuperUser) }),
