                            <td>{user.department || user.department_details?.name || '—'}</td>
                            <td>
                              <button className="leave-text-button" type="button" onClick={() => startAdminUserEdit(user)}>Edit</button>
                              <button className="leave-text-button" type="button" onClick={() => deleteAdminUser(user.id)}>Delete</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
                {editingAdminUserId && <form onSubmit={saveAdminUser} className="admin-form admin-edit-form">
