                  <div className="leave-form-row"><label>Phone<input value={adminUserForm.phone_number} onChange={(event) => setAdminUserForm({ ...adminUserForm, phone_number: event.target.value })} required /></label><label>Department<input value={adminUserForm.department} onChange={(event) => setAdminUserForm({ ...adminUserForm, department: event.target.value })} required /></label></div>
                  <div className="leave-form-row"><label>Job title<input value={adminUserForm.job_position_title} onChange={(event) => setAdminUserForm({ ...adminUserForm, job_position_title: event.target.value })} /></label><label>Employer<input value={adminUserForm.employer} onChange={(event) => setAdminUserForm({ ...adminUserForm, employer: event.target.value })} /></label></div>
                  {isSuperAdmin && <><label>Role<select value={adminUserForm.role} onChange={(event) => setAdminUserForm({ ...adminUserForm, role: event.target.value })}><option value="employee">Employee</option><option value="manager">Manager</option><option value="hr_admin">HR Admin</option></select></label><label className="checkbox-row"><input type="checkbox" checked={adminUserForm.is_superuser} onChange={(event) => setAdminUserForm({ ...adminUserForm, is_superuser: event.target.checked })} /> Super admin privileges</label></>}
                  <div className="leave-modal-actions"><button type="button" className="leave-secondary-button" onClick={() => setEditingAdminUserId(null)}>Cancel</button><button type="submit" className="leave-primary-button">Save changes</button></div>
